#!/usr/bin/env python3
from pathlib import Path
import subprocess, sys, re

FILES = {
    "seed_v85_gate.py": "\nimport json, subprocess, sys, time\nfrom datetime import datetime\nfrom pathlib import Path\n\nREPORT_FILE = Path(\"seed_v85_gate_report.json\")\nCORE_MODULES = [\n    \"seed_self_state_v85.py\", \"seed_recovery_v82.py\", \"seed_runtime_v83.py\",\n    \"seed_privacy_backup_v84.py\", \"seed_release_candidate_v85.py\",\n    \"seed_v85_systems.py\", \"seed_v85_gate.py\", \"seed_v85_commands.py\",\n    \"seed_natural_intent_router_v85.py\", \"seed_v81_gate.py\", \"seed_v75_gate.py\",\n]\n\ndef now(): return datetime.now().isoformat(timespec=\"seconds\")\n\ndef compile_module(module):\n    if not Path(module).exists():\n        return {\"module\": module, \"ok\": False, \"stderr\": \"missing\"}\n    p = subprocess.run([sys.executable, \"-m\", \"py_compile\", module], capture_output=True, text=True, timeout=20)\n    return {\"module\": module, \"ok\": p.returncode == 0, \"stderr\": p.stderr[-1200:]}\n\ndef read_report(path):\n    p = Path(path)\n    if not p.exists(): return {}\n    try: return json.loads(p.read_text(errors=\"ignore\"))\n    except Exception: return {}\n\ndef report_ready(path, max_age_seconds=86400):\n    p = Path(path)\n    if not p.exists():\n        return False, {\"source\": \"missing_report\", \"path\": str(p)}\n    data = read_report(path)\n    age = time.time() - p.stat().st_mtime\n    return data.get(\"ready\") is True and age <= max_age_seconds, {\n        \"source\": \"cached_report\", \"path\": str(p), \"age_seconds\": round(age, 1),\n        \"ready\": data.get(\"ready\"), \"version\": data.get(\"version\")\n    }\n\ndef run_v85_gate(deep=False):\n    checks = [compile_module(m) for m in CORE_MODULES]\n    modules_ok = all(c[\"ok\"] for c in checks)\n\n    v81_ok, v81_meta = report_ready(\"seed_v81_gate_report.json\")\n    v75_ok, v75_meta = report_ready(\"seed_v75_gate_report.json\")\n\n    if deep:\n        for script, key in [(\"seed_v81_gate.py\", \"v81\"), (\"seed_v75_gate.py\", \"v75\")]:\n            try:\n                p = subprocess.run([sys.executable, script], capture_output=True, text=True, timeout=240)\n                meta = {\"source\": \"deep_subprocess\", \"returncode\": p.returncode, \"stdout_tail\": p.stdout[-2000:], \"stderr_tail\": p.stderr[-2000:]}\n                if key == \"v81\": v81_ok, v81_meta = (p.returncode == 0), meta\n                else: v75_ok, v75_meta = (p.returncode == 0), meta\n            except Exception as e:\n                if key == \"v81\": v81_ok, v81_meta = False, {\"source\": \"deep_subprocess\", \"error\": str(e)}\n                else: v75_ok, v75_meta = False, {\"source\": \"deep_subprocess\", \"error\": str(e)}\n\n    try:\n        from seed_self_state_v85 import build_self_state\n        s = build_self_state()\n        truth_ok = s.get(\"true_current_version\") in {\"v85.0.0\", \"v85.1.0\", \"v85.2.0\"}\n        truth_meta = {\"current\": s.get(\"true_current_version\"), \"green_layers\": s.get(\"installed_layers_green\", [])}\n    except Exception as e:\n        truth_ok, truth_meta = False, {\"error\": str(e)}\n\n    try:\n        from seed_runtime_v83 import install_seed_script\n        script = install_seed_script()\n        script_ok = script.get(\"ok\") is True and Path(\"seed\").exists()\n    except Exception as e:\n        script, script_ok = {\"ok\": False, \"error\": str(e)}, False\n\n    try:\n        from seed_recovery_v82 import recovery_summary\n        rec = recovery_summary()\n        recovery_ok = rec.get(\"ok\") is True\n    except Exception as e:\n        rec, recovery_ok = {\"ok\": False, \"error\": str(e)}, False\n\n    report = {\n        \"created_at\": now(), \"version\": \"v85.2.0\",\n        \"ready\": modules_ok and v81_ok and v75_ok and truth_ok and script_ok and recovery_ok,\n        \"modules_ok\": modules_ok, \"v81_ok\": v81_ok, \"v75_ok\": v75_ok,\n        \"truth_ok\": truth_ok, \"script_ok\": script_ok, \"recovery_ok\": recovery_ok,\n        \"module_checks\": checks,\n        \"details\": {\n            \"v81\": v81_meta, \"v75\": v75_meta, \"truth\": truth_meta,\n            \"runtime_script\": script,\n            \"recovery\": {\"ok\": rec.get(\"ok\"), \"blockers\": rec.get(\"blockers\"), \"warnings\": rec.get(\"warnings\")},\n            \"mode\": \"deep\" if deep else \"fast_cached\"\n        },\n        \"note\": \"v85.2 fast gate avoids re-running slow nested gates unless --deep is used.\"\n    }\n    REPORT_FILE.write_text(json.dumps(report, indent=4, ensure_ascii=False))\n    return report\n\ndef show_v85_gate(deep=False):\n    r = run_v85_gate(deep=deep)\n    print(\"\\n=== SEED v85.2 FAST REAL V1 PREP GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"v81 OK: {r['v81_ok']}\")\n    print(f\"v75 OK: {r['v75_ok']}\")\n    print(f\"Truth OK: {r['truth_ok']}\")\n    print(f\"Script OK: {r['script_ok']}\")\n    print(f\"Recovery OK: {r['recovery_ok']}\")\n    print(f\"Details: {r['details']}\")\n\nif __name__ == \"__main__\":\n    show_v85_gate(deep=\"--deep\" in sys.argv)\n",
    "seed_recovery_v82.py": "\nimport json, os, subprocess, sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nREPORT_FILE = Path(\"seed_recovery_report_v82.json\")\nLAST_GREEN_FILE = Path(\"seed_last_green_checkpoint_v82.json\")\nROLLBACK_NOTES = Path(\"seed_recovery_rollback_notes_v82.md\")\nCORE_RUNTIME_FILES = [\n    \"seed_cli.py\", \"seed_commands.py\", \"seed_local_chat_v701.py\",\n    \"seed_v85_gate.py\", \"seed_v85_systems.py\", \"seed_self_state_v85.py\",\n    \"seed_recovery_v82.py\", \"seed_runtime_v83.py\", \"seed_privacy_backup_v84.py\",\n    \"seed_release_candidate_v85.py\", \"seed_v81_gate.py\", \"seed_v75_gate.py\",\n    \"seed_v74_gate.py\", \"seed_v731_gate.py\",\n]\ndef now(): return datetime.now().isoformat(timespec=\"seconds\")\ndef compile_file(path):\n    try:\n        p = subprocess.run([sys.executable, \"-m\", \"py_compile\", str(path)], capture_output=True, text=True, timeout=20)\n        return {\"file\": str(path), \"ok\": p.returncode == 0, \"stderr\": p.stderr[-1200:]}\n    except Exception as e:\n        return {\"file\": str(path), \"ok\": False, \"stderr\": str(e)}\ndef compile_all():\n    files = [Path(f) for f in CORE_RUNTIME_FILES if Path(f).exists()]\n    checks = [compile_file(p) for p in files]\n    failed = [c for c in checks if not c[\"ok\"]]\n    return {\"ok\": len(failed) == 0, \"count\": len(checks), \"failed\": failed, \"checks\": checks}\ndef recursion_guard():\n    warnings = []\n    patterns = [\n        (\"seed_self_state_v741.py\", \"seed_v75_gate\", \"v75 self-state should not call v75 gate\"),\n        (\"seed_self_state_v81.py\", \"seed_v81_gate\", \"v81 self-state should not call v81 gate\"),\n        (\"seed_self_state_v85.py\", \"seed_v85_gate\", \"v85 self-state should not call v85 gate\"),\n    ]\n    for filename, needle, message in patterns:\n        p = Path(filename)\n        if p.exists() and needle in p.read_text(errors=\"ignore\"):\n            warnings.append({\"file\": filename, \"warning\": message})\n    return {\"ok\": len(warnings) == 0, \"warnings\": warnings}\ndef dependency_check():\n    import shutil\n    deps = {name: shutil.which(name) for name in [\"ffmpeg\", \"say\", \"aider\", \"git\"]}\n    try:\n        import faster_whisper\n        deps[\"faster_whisper\"] = True\n    except Exception:\n        deps[\"faster_whisper\"] = False\n    return {\"ok\": bool(deps.get(\"git\")), \"deps\": deps}\ndef storage_check():\n    try:\n        u = os.statvfs(\".\")\n        free_gb = u.f_bavail * u.f_frsize / (1024**3)\n        total_gb = u.f_blocks * u.f_frsize / (1024**3)\n        return {\"ok\": free_gb > 3, \"free_gb\": round(free_gb, 2), \"total_gb\": round(total_gb, 2)}\n    except Exception as e:\n        return {\"ok\": False, \"error\": str(e)}\ndef mark_last_green(label=\"manual_green_checkpoint\"):\n    data = {\"created_at\": now(), \"version\": \"v85.2.0\", \"label\": label, \"cwd\": str(Path(\".\").resolve())}\n    try:\n        p = subprocess.run([\"git\", \"rev-parse\", \"--short\", \"HEAD\"], capture_output=True, text=True, timeout=8)\n        if p.returncode == 0: data[\"git_head\"] = p.stdout.strip()\n    except Exception: pass\n    LAST_GREEN_FILE.write_text(json.dumps(data, indent=4))\n    return data\ndef recovery_summary():\n    comp, guard, deps, storage = compile_all(), recursion_guard(), dependency_check(), storage_check()\n    blockers, warnings = [], []\n    if not comp[\"ok\"]: blockers.append(f\"{len(comp['failed'])} core runtime compile failures\")\n    if not guard[\"ok\"]: blockers.append(\"recursion guard warning\")\n    if not deps[\"ok\"]: blockers.append(\"missing critical dependency: git\")\n    if not storage[\"ok\"]: warnings.append(\"storage warning\")\n    data = {\n        \"created_at\": now(), \"version\": \"v85.2.0\", \"ok\": len(blockers) == 0,\n        \"blockers\": blockers, \"warnings\": warnings,\n        \"compile\": {\"ok\": comp[\"ok\"], \"count\": comp[\"count\"], \"failed\": comp[\"failed\"][:10]},\n        \"recursion_guard\": guard, \"dependencies\": deps, \"storage\": storage,\n        \"last_green\": json.loads(LAST_GREEN_FILE.read_text()) if LAST_GREEN_FILE.exists() else None,\n        \"note\": \"Fast recovery checks only core runtime files, not old installers.\"\n    }\n    REPORT_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\ndef write_rollback_notes():\n    s = recovery_summary()\n    ROLLBACK_NOTES.write_text(\"\\n\".join([\n        \"# Seed v85.2 Recovery Notes\", \"\", f\"Created: {now()}\",\n        f\"OK: {s.get('ok')}\", f\"Blockers: {s.get('blockers')}\", f\"Warnings: {s.get('warnings')}\",\n        \"\", \"Rollback:\", \"1. Stop Seed servers with Ctrl+C.\",\n        \"2. Restore latest seed_backup_*_green folder.\",\n        \"3. Or use git reset --hard <green_commit>.\",\n        \"4. Re-run seed_v85_gate.py.\",\n    ]))\n    return {\"ok\": True, \"file\": str(ROLLBACK_NOTES)}\ndef show_recovery():\n    d = recovery_summary()\n    print(\"\\n=== SEED v85.2 FAST RECOVERY ===\")\n    print(f\"OK: {d['ok']}\")\n    print(f\"Blockers: {d['blockers']}\")\n    print(f\"Warnings: {d['warnings']}\")\n    print(f\"Compile: {d['compile']['ok']} ({d['compile']['count']} core runtime files)\")\n    print(f\"Deps: {d['dependencies']['deps']}\")\nif __name__ == \"__main__\":\n    show_recovery()\n",
    "seed_v85_systems.py": "\nimport json\nfrom datetime import datetime\nfrom pathlib import Path\nSTATE_FILE = Path(\"seed_v85_systems_state.json\")\ndef now(): return datetime.now().isoformat(timespec=\"seconds\")\ndef safe(title, summary, fn):\n    try:\n        data = fn()\n        return {\"title\": title, \"summary\": summary, \"status\": \"ok\" if data.get(\"ok\", True) else \"warning\", \"data\": data}\n    except Exception as e:\n        return {\"title\": title, \"summary\": summary, \"status\": \"error\", \"error\": str(e)}\ndef build_v85_state():\n    cards = [\n        safe(\"v82 Recovery\", \"Fast core runtime compile checks and rollback notes.\", lambda: __import__(\"seed_recovery_v82\", fromlist=[\"recovery_summary\"]).recovery_summary()),\n        safe(\"v83 One-Command Runtime\", \"Seed can start via ./seed or seed_start.sh.\", lambda: __import__(\"seed_runtime_v83\", fromlist=[\"runtime_status\"]).runtime_status()),\n        safe(\"v84 Backup/Privacy\", \"Backup, export memory, forget by keyword.\", lambda: __import__(\"seed_privacy_backup_v84\", fromlist=[\"privacy_status\"]).privacy_status()),\n        safe(\"v85 Release Candidate\", \"RC report and README generation.\", lambda: __import__(\"seed_release_candidate_v85\", fromlist=[\"release_candidate_summary\"]).release_candidate_summary()),\n        safe(\"Self-State Truth\", \"Current version override is v85.x.\", lambda: __import__(\"seed_self_state_v85\", fromlist=[\"build_self_state\"]).build_self_state()),\n    ]\n    data = {\"created_at\": now(), \"version\": \"v85.2.0\", \"ok\": all(c[\"status\"] != \"error\" for c in cards), \"cards\": cards}\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\ndef show_v85_status():\n    data = build_v85_state()\n    print(\"\\n=== SEED v85.2 FAST REAL V1 PREP STATUS ===\")\n    print(f\"OK: {data['ok']}\")\n    for c in data[\"cards\"]:\n        print(f\"- {c['title']}: {c['status']} \u2014 {c['summary']}\")\nif __name__ == \"__main__\":\n    show_v85_status()\n",
}
for path, text in FILES.items():
    Path(path).write_text(text.strip() + "\n")
    print("Wrote", path)

p = Path("seed_config.py")
text = p.read_text(errors="ignore") if p.exists() else 'SEED_VERSION = "v85.2.0"\n'
text = re.sub(r'^SEED_VERSION\s*=\s*".*?"', 'SEED_VERSION = "v85.2.0"', text, flags=re.M)
if "SEED_V852_FAST_GATE" not in text:
    text += "\nSEED_V852_FAST_GATE = True\n"
p.write_text(text)
print("Updated seed_config.py")

p = Path("Seed_Core.md")
text = p.read_text(errors="ignore") if p.exists() else ""
if "Seed v85.2 — Fast Gate Hotfix" not in text:
    text += """
## Seed v85.2 — Fast Gate Hotfix

Fixes slow v85 validation:
- v85 gate no longer re-runs slow nested v81 gate by default.
- v85 gate uses recent seed_v81_gate_report.json.
- --deep mode still exists for slow full validation.
- Recovery checks only core runtime files, not old installers.
"""
p.write_text(text)
print("Updated Seed_Core.md")

for m in ["seed_v85_gate.py", "seed_recovery_v82.py", "seed_v85_systems.py", "seed_commands.py"]:
    if Path(m).exists():
        proc = subprocess.run([sys.executable, "-m", "py_compile", m], capture_output=True, text=True, timeout=30)
        print("$ python -m py_compile", m)
        if proc.returncode == 0:
            print("OK")
        else:
            print(proc.stderr)
            sys.exit(proc.returncode)
print("\nSeed v85.2 fast gate hotfix installed.")
